(() => {
  'use strict';
  const TODAY='2026-10-24';
  const seeds=[
    {id:'m-calag',type:'funding',date:'2026-11-02',title:'CalAgPlate due',note:'Mon, 9am PT',emphasis:true},
    {id:'m-ava-close',type:'funding',date:'2026-11-30',title:'Ava window closes',note:'End of Nov, date to confirm',estimated:true},
    {id:'m-ava-award',type:'funding',date:'2026-12-15',title:'Ava awards',note:'December',estimated:true},
    {id:'m-climate',type:'funding',date:'2027-01-15',title:'Climate Action Corps',note:'Host applications open',estimated:true},
    {id:'m-harvest',type:'giving',date:'2026-11-14',title:'Harvest giving day',note:'Seasonal community fundraiser'},
    {id:'m-monthly',type:'giving',date:'2026-11-30',title:'Monthly giving closes',note:'November community support'},
    {id:'m-year-end',type:'giving',date:'2026-12-31',title:'Year-end giving',note:'Final day of the annual appeal'}
  ];
  let api, type='funding', offset=0, custom=[],edited={};
  try{const stored=JSON.parse(localStorage.getItem('roots-milestones-v1')||'{}');custom=stored.custom||[];edited=stored.edited||{};}catch{}
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const d=s=>new Date(`${s}T12:00:00`);
  const iso=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
  const fmt=s=>d(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
  const eventDate=e=>e.date||`2026-${{OCT:'10',NOV:'11',DEC:'12'}[e.month]||'10'}-${String(e.day).padStart(2,'0')}`;
  const arrow=back=>`<svg class="${back?'timeline-back':''}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>`;
  function range(){if(type==='events'){const start=d(TODAY);start.setDate(start.getDate()+offset*28);const end=new Date(start);end.setDate(end.getDate()+28);return {start:iso(start),end:iso(end)};}const start=d('2026-10-15'),end=d('2027-01-31');start.setMonth(start.getMonth()+offset*3);end.setMonth(end.getMonth()+offset*3);return {start:iso(start),end:iso(end)};}
  function all(){const events=api.getEvents().map(e=>({id:`event-${e.id}`,eventId:e.id,type:'events',date:eventDate(e),title:e.title,note:`${e.time} · ${e.attendees} going`}));return [...seeds,...custom,...events].map(m=>({...m,...edited[m.id]}));}
  function visible(){const r=range();return all().filter(m=>m.type===type&&m.date>=r.start&&m.date<=r.end).sort((a,b)=>a.date.localeCompare(b.date));}
  function save(){try{localStorage.setItem('roots-milestones-v1',JSON.stringify({custom,edited}));}catch{api.toast('Browser storage unavailable. Milestones last for this visit.');}}
  function update(selector){api.render();if(selector)document.querySelector(selector)?.focus({preventScroll:true});}
  function render(){const r=range(),items=visible(),start=d(r.start).getTime(),end=d(r.end).getTime();const x=day=>(d(day).getTime()-start)/(end-start)*100;const marks=[];for(let tick=new Date(d(r.start).getFullYear(),d(r.start).getMonth()+1,1,12);tick<=d(r.end);tick=new Date(tick.getFullYear(),tick.getMonth()+1,1,12))marks.push({day:iso(tick),label:tick.toLocaleDateString('en-US',{month:'short'})});
    const minWidth=Math.max(1080,items.length*240+120);const now=TODAY>=r.start&&TODAY<=r.end;
    // Alternate annotations across two lanes; stagger crowded dates with light leader lines.
    const laneLast=[-200,-200];
    const notes=items.map((m,i)=>{const up=i%2===0, lane=up?0:1,point=x(m.date),px=point/100*minWidth;let labelPx=Math.max(12,Math.min(px-7,minWidth-248));labelPx=Math.max(labelPx,laneLast[lane]+238);laneLast[lane]=labelPx;const labelPercent=labelPx/minWidth*100;return `<div class="timeline-milestone ${up?'above':'below'} ${m.emphasis?'emphasis':''}" style="--point:${point}%;--label:${labelPercent}%;--leader:${(labelPx+7-px)/minWidth*100}%"><button class="timeline-dot" data-timeline="open" data-id="${escape(m.id)}" aria-label="${escape(m.title)}, ${fmt(m.date)}${m.estimated?', approximate date':''}"></button><button class="timeline-annotation" data-timeline="open" data-id="${escape(m.id)}"><strong>${escape(m.title)}</strong><span>${escape(m.note||fmt(m.date))}${m.estimated&&!/confirm|approx/i.test(m.note||'')?' · Date to confirm':''}</span></button></div>`;}).join('');
    return `<section class="timeline-section" aria-labelledby="timeline-heading"><header class="timeline-heading"><div><h2 id="timeline-heading">On the horizon</h2><p>The dates worth keeping in view.</p></div><button class="button quiet" data-timeline="add"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>Add milestone</button></header><div class="timeline-toolbar"><div class="timeline-filters" role="group" aria-label="Timeline activities">${[['funding','Funding deadlines'],['events','Community events'],['giving','Giving campaigns']].map(([value,label])=>`<button data-timeline="type" data-type="${value}" class="${type===value?'active':''}" aria-pressed="${type===value}">${label}</button>`).join('')}</div><div class="timeline-range"><button class="icon-button" data-timeline="prev" aria-label="Previous date range">${arrow(true)}</button><span>${fmt(r.start).replace(', 2026','').replace(', 2027','')} – ${fmt(r.end)}</span><button class="icon-button" data-timeline="next" aria-label="Next date range">${arrow(false)}</button><button class="timeline-today" data-timeline="today">Today</button></div></div><div class="timeline-scroll" tabindex="0" role="region" aria-label="Horizontal milestone timeline. Scroll to view all dates."><div class="timeline-canvas" style="min-width:${minWidth}px"><div class="timeline-line"></div>${marks.map(m=>`<div class="timeline-month" style="left:${x(m.day)}%"><i></i><span>${m.label}</span></div>`).join('')}${now?`<div class="timeline-current" style="left:${x(TODAY)}%"><i></i><span>Today</span></div>`:''}${notes}${!items.length?'<div class="timeline-empty">No milestones in this range.<br><button data-timeline="add">Add one to keep it in view.</button></div>':''}</div></div><footer class="timeline-foot"><span>${type==='funding'?'Illustrative dates from your reference · Confirm program deadlines before applying.':'Illustrative community calendar · Select a milestone for details.'}</span><span>Scroll to explore ${arrow(false)}</span></footer></section>`;
  }
  function form(id){const m=id?all().find(x=>x.id===id):{type,date:TODAY,title:'',note:''};if(!m)return;if(m.eventId){api.eventDetail(m.eventId);return;}api.openDialog('Community timeline',`<h2 id="dialog-title">${id?escape(m.title):'A date to remember.'}</h2><p class="lead">${id?'Keep the date and details up to date.':'Add a funding deadline, community event, or giving milestone.'}</p><form id="timeline-form" data-id="${escape(id||'')}"><div class="form-field"><label for="milestone-title">Milestone</label><input id="milestone-title" name="title" value="${escape(m.title)}" required maxlength="70" placeholder="e.g. Community fundraiser"></div><div class="form-row"><div class="form-field"><label for="milestone-date">Date</label><input id="milestone-date" name="date" type="date" value="${m.date}" required></div><div class="form-field"><label for="milestone-type">Activity type</label><select id="milestone-type" name="type">${[['funding','Funding deadline'],['events','Community event'],['giving','Giving campaign']].map(([value,label])=>`<option value="${value}" ${m.type===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="form-field"><label for="milestone-note">Supporting detail</label><input id="milestone-note" name="note" value="${escape(m.note)}" maxlength="90" placeholder="e.g. Applications close at 5pm"></div><label class="consent-row"><input type="checkbox" name="estimated" ${m.estimated?'checked':''}>Date is approximate or still needs confirmation.</label><button type="submit" class="button primary wide">Save milestone</button><p class="source-note">This is a local planning demo. Program dates are illustrative, and no application or donation is submitted.</p></form>`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-timeline]');if(!b||!api)return;const a=b.dataset.timeline;if(a==='type'){type=b.dataset.type;offset=0;update(`[data-timeline="type"][data-type="${type}"]`);}else if(a==='prev'||a==='next'){offset+=a==='next'?1:-1;update(`[data-timeline="${a}"]`);}else if(a==='today'){offset=0;update('[data-timeline="today"]');}else if(a==='open')form(b.dataset.id);else if(a==='add')form();});
  document.addEventListener('submit',e=>{if(e.target.id!=='timeline-form')return;e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title){const el=document.getElementById('milestone-title');el.setCustomValidity('Enter a milestone name.');el.reportValidity();return;}const values={title,date:String(f.get('date')),type:String(f.get('type')),note:String(f.get('note')).trim(),estimated:f.has('estimated')};if(e.target.dataset.id)edited[e.target.dataset.id]=values;else custom.push({...values,id:`milestone-${Date.now()}`});type=values.type;offset=0;for(let i=0;i<600;i++){const r=range();if(values.date<r.start)offset--;else if(values.date>r.end)offset++;else break;}save();api.closeDialog();update('[data-timeline="add"]');api.toast('Milestone saved to your timeline.');});
  window.RootsTimeline={configure(callbacks){api=callbacks;},render};
})();
